#include <bits/stdc++.h>
using namespace std;

// Decodes the JSON string literal starting at raw[p] == '"' into Unicode code points
// (UTF-8 bytes and \u escapes, joining surrogate pairs); leaves p after the closing quote.
int hex4(const string &raw, size_t p) {
    return stoi(raw.substr(p, 4), nullptr, 16);
}

vector<int> parseJsonString(const string &raw, size_t &p) {
    vector<int> out;
    p++;
    while (raw[p] != '"') {
        unsigned char c = raw[p];
        if (c == '\\') {
            char e = raw[p + 1];
            p += 2;
            if (e == 'u') {
                int u = hex4(raw, p);
                p += 4;
                if (u >= 0xD800 && u < 0xDC00 && raw.compare(p, 2, "\\u") == 0) {
                    int lo = hex4(raw, p + 2);
                    if (lo >= 0xDC00 && lo < 0xE000) {
                        u = 0x10000 + ((u - 0xD800) << 10) + (lo - 0xDC00);
                        p += 6;
                    }
                }
                out.push_back(u);
            } else {
                const string from = "\"\\/bfnrt", to = "\"\\/\b\f\n\r\t";
                out.push_back(to[from.find(e)]);
            }
        } else if (c < 0x80) {
            out.push_back(c);
            p++;
        } else {
            int len = c >= 0xF0 ? 4 : c >= 0xE0 ? 3 : 2;
            int cp = c & (0x7F >> len);
            for (int i = 1; i < len; i++) cp = (cp << 6) | (raw[p + i] & 0x3F);
            out.push_back(cp);
            p += len;
        }
    }
    p++;
    return out;
}

int main() {
    string raw((istreambuf_iterator<char>(cin)), istreambuf_iterator<char>());
    size_t p = raw.find('"');
    vector<int> s = parseJsonString(raw, p);
    p = raw.find(',', p);
    int k = stoi(raw.substr(p + 1));
    long long answer = 0;
    // Only the window changes: compare symmetric pairs from the outside in; the first
    // differing pair decides whether the reversed string is smaller.
    for (int start = 0; start + k <= (int)s.size(); start++) {
        int left = start, right = start + k - 1;
        while (left < right && s[left] == s[right]) { left++; right--; }
        if (left < right && s[right] < s[left]) answer++;
    }
    cout << answer << "\n";
}

import java.io.*;
