public class Main {
    static byte[] raw;
    static int pos;

    static int hex4(int p) {
        return Integer.parseInt(new String(raw, p, 4), 16);
    }

    // Decodes the JSON string literal starting at raw[pos] == '"' into Unicode code points
    // (UTF-8 bytes and backslash-u escapes, joining surrogate pairs); leaves pos after the closing quote.
    static int[] parseJsonString() {
        int[] out = new int[16];
        int size = 0;
        pos++;
        while (raw[pos] != '"') {
            int c = raw[pos] & 0xFF, cp;
            if (c == '\\') {
                char e = (char) raw[pos + 1];
                pos += 2;
                if (e == 'u') {
                    cp = hex4(pos);
                    pos += 4;
                    if (cp >= 0xD800 && cp < 0xDC00 && raw[pos] == '\\' && raw[pos + 1] == 'u') {
                        int lo = hex4(pos + 2);
                        if (lo >= 0xDC00 && lo < 0xE000) {
                            cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                            pos += 6;
                        }
                    }
                } else {
                    cp = "\"\\/\b\f\n\r\t".charAt("\"\\/bfnrt".indexOf(e));
                }
            } else if (c < 0x80) {
                cp = c;
                pos++;
            } else {
                int len = c >= 0xF0 ? 4 : c >= 0xE0 ? 3 : 2;
                cp = c & (0x7F >> len);
                for (int i = 1; i < len; i++) cp = (cp << 6) | (raw[pos + i] & 0x3F);
                pos += len;
            }
            if (size == out.length) out = Arrays.copyOf(out, size * 2);
            out[size++] = cp;
        }
        pos++;
        return Arrays.copyOf(out, size);
    }

    public static void main(String[] args) throws IOException {
        raw = System.in.readAllBytes();
        while (raw[pos] != '"') pos++;
        int[] s = parseJsonString();
        while (raw[pos] != ',') pos++;
        int k = 0;
        for (pos++; pos < raw.length; pos++) if (raw[pos] >= '0' && raw[pos] <= '9') k = k * 10 + (raw[pos] - '0');
        long answer = 0;
        // Only the window changes: compare symmetric pairs from the outside in; the first
        // differing pair decides whether the reversed string is smaller.
        for (int start = 0; start + k <= s.length; start++) {
            int left = start, right = start + k - 1;
            while (left < right && s[left] == s[right]) {
                left++;
                right--;
            }
            if (left < right && s[right] < s[left]) answer++;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

var raw []byte
var pos int

func hex4(p int) int {
	v, _ := strconv.ParseInt(string(raw[p:p+4]), 16, 32)
	return int(v)
}

// Decodes the JSON string literal starting at raw[pos] == '"' into Unicode code points
// (UTF-8 bytes and \u escapes, joining surrogate pairs); leaves pos after the closing quote.
func parseJSONString() []int {
	var out []int
	pos++
	for raw[pos] != '"' {
		c := int(raw[pos])
		var cp int
		if c == '\\' {
			e := raw[pos+1]
			pos += 2
			if e == 'u' {
				cp = hex4(pos)
				pos += 4
				if cp >= 0xD800 && cp < 0xDC00 && raw[pos] == '\\' && raw[pos+1] == 'u' {
					if lo := hex4(pos + 2); lo >= 0xDC00 && lo < 0xE000 {
						cp = 0x10000 + (cp-0xD800)<<10 + (lo - 0xDC00)
						pos += 6
					}
				}
			} else {
				cp = int("\"\\/\b\f\n\r\t"[strings.IndexByte("\"\\/bfnrt", e)])
			}
		} else if c < 0x80 {
			cp = c
			pos++
		} else {
			n := 2
			if c >= 0xF0 {
				n = 4
			} else if c >= 0xE0 {
				n = 3
			}
			cp = c & (0x7F >> n)
			for i := 1; i < n; i++ {
				cp = cp<<6 | int(raw[pos+i]&0x3F)
			}
			pos += n
		}
		out = append(out, cp)
	}
	pos++
	return out
}

func main() {
	raw, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	for raw[pos] != '"' {
		pos++
	}
	s := parseJSONString()
	for raw[pos] != ',' {
		pos++
	}
	k := 0
	for pos++; pos < len(raw); pos++ {
		if raw[pos] >= '0' && raw[pos] <= '9' {
			k = k*10 + int(raw[pos]-'0')
		}
	}
	answer := 0
	// Only the window changes: compare symmetric pairs from the outside in; the first
	// differing pair decides whether the reversed string is smaller.
	for start := 0; start+k <= len(s); start++ {
		left, right := start, start+k-1
		for left < right && s[left] == s[right] {
			left++
			right--
		}
		if left < right && s[right] < s[left] {
			answer++
		}
	}
	fmt.Println(answer)
}
